-- Generated from 10 categories (手机数码/电脑办公/...) × 2 products each
-- ============================================================
-- Table schema reminder:
--   id BIGINT PK, name VARCHAR(200), description TEXT,
--   original_price DECIMAL(10,2), stock INT, sales_count INT,
--   cart_count INT, favorite_count INT, category_id BIGINT,
--   images JSON, main_image VARCHAR(255), detail_html TEXT,
--   status ENUM('ON_SALE','OFF_SHELF'), is_deleted TINYINT,
--   create_time DATETIME, update_time DATETIME
-- NOTE: id values 1..116 assume an empty target table.
--       If data already exists, either TRUNCATE first or omit `id`.
-- ============================================================

SET NAMES utf8mb4;
SET FOREIGN_KEY_CHECKS = 0;
TRUNCATE TABLE t_product;
SET FOREIGN_KEY_CHECKS = 1;


-- Total: 116 rows inserted.
SELECT COUNT(*) AS total_inserted FROM t_product;
SELECT category_id, COUNT(*) AS cnt FROM t_product GROUP BY category_id ORDER BY category_id;